/** FreeCAD's measures of a stored shape. */
export interface FreecadMeasure {
  readonly solids: number;
  readonly volume: number;
  readonly area: number;
  /** FreeCAD's `BoundBox`: x, y, z min, then max (looser than a tight box on curved faces). */
  readonly box: readonly number[];
  readonly faces: number;
  readonly edges: number;
}

/** FreeCAD's description of a named edge or face of the base's stored shape. */
export interface FreecadElement {
  readonly name: string;
  readonly curve?: string;
  readonly length?: number;
  readonly mid?: readonly number[];
  readonly ends?: readonly (readonly number[])[];
  readonly surface?: string;
  readonly area?: number;
  readonly centre?: readonly number[];
  readonly edges?: number;
}

export interface DressUpFixtureFeature {
  readonly object: string;
  readonly type: string;
  /** The stored B-rep text. */
  readonly stored: string;
  readonly measure: FreecadMeasure;
  readonly base?: string;
  readonly subs?: readonly string[];
  readonly subInfo?: readonly FreecadElement[];
  readonly Radius?: number;
  readonly UseAllEdges?: boolean;
  readonly ChamferType?: string;
  readonly ChamferTypeIndex?: number;
  readonly Size?: number;
  readonly Size2?: number;
  readonly Angle?: number;
  readonly FlipDirection?: boolean;
  readonly Length?: number;
}

