/** The properties a pad's spec writes that a dress-up doesn't have. */
const NOT_A_DRESSUP = ['Profile', 'Type', 'Reversed', 'Midplane', 'Length', 'Length2'];

/** A dress-up's object as FreeCAD stores it, from the fixture's values (`change` overrides them). */
export function dressUpSpec(
  f: DressUpFixtureFeature,
  change: Partial<DressUpFixtureFeature> = {},
): FeatureSpec {
  const v = { ...f, ...change };
  const props = [
    linkSub('Base', v.base as string, [...(v.subs ?? [])]),
    bool('UseAllEdges', v.UseAllEdges ?? false),
  ];
  if (v.type === 'PartDesign::Fillet') props.push(num('Radius', v.Radius as number));
  else
    props.push(
      choice('ChamferType', v.ChamferTypeIndex ?? 0),
      num('Size', v.Size as number),
      num('Size2', v.Size2 as number),
      num('Angle', v.Angle as number, 'App::PropertyAngle'),
      bool('FlipDirection', v.FlipDirection ?? false),
    );
  return { name: v.object, type: v.type, omit: NOT_A_DRESSUP, props, stored: v.stored };
}
